def compact_ranges(values: list[int]) -> str:
    if not values:
        return ""

    nums = sorted(set(values))
    result = []
    start = prev = nums[0]

    for value in nums[1:]:
        if value == prev + 1:
            prev = value
            continue

        if prev - start >= 2:
            result.append(f"{start}-{prev}")
        else:
            result.extend(str(n) for n in range(start, prev + 1))

        start = prev = value

    if prev - start >= 2:
        result.append(f"{start}-{prev}")
    else:
        result.extend(str(n) for n in range(start, prev + 1))

    return ",".join(result)

